SELECT 'core-2026-09-v4','reflexive-reciprocal','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"reflexive-reciprocal","title":"Reflexive and reciprocal pronouns","level":"B1","order":53,"summary":"Distinguish doing something to yourself, doing it alone and doing it to one another.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["The same participant twice","Emphasis and independence","Reciprocal actions","Use a reflexive only when its role needs one"],"rules":[{"title":"The same participant twice","explanation":"A reflexive pronoun can be used when the subject and object refer to the same person or thing. Its form matches the subject: myself, yourself, himself, herself, itself, ourselves, yourselves, themselves.","pattern":"She introduced **herself**.","commonMistakes":["Her and herself are not interchangeable: her normally refers to someone other than the subject in this example."],"examples":["“She prepared the visitor guide by **herself**.” Choose the matching reflexive.","“She restored the old portrait by **herself**.” Choose the matching reflexive."],"skill":"form"},{"title":"Emphasis and independence","explanation":"A reflexive can emphasise that the subject personally did the action. **By + reflexive** usually means alone or without help. **For + reflexive** means for one’s own benefit. These meanings are related but not identical.","pattern":"I made it **myself**. / I did it **by myself**.","commonMistakes":["By myself says without company or help; for myself says who benefits."],"examples":["“We prepared the visitor guide by **ourselves**.”","“We restored the old portrait by **ourselves**.”"],"skill":"meaning"},{"title":"Reciprocal actions","explanation":"Each other and one another express a reciprocal relationship: A acts on B and B acts on A. They are not equivalent to themselves, where each participant’s action returns to that same participant.","pattern":"They introduced **each other**.","commonMistakes":["They looked at themselves means each looked at their own reflection; each other means they looked across at one another."],"examples":["“The two assistants helped each other to prepare the visitor guide.” What does “each other” show? → **Each assistant helped the other assistant.**","“The two assistants helped each other to restore the old portrait.” What does “each other” show? → **Each assistant helped the other assistant.**"],"skill":"contrast"},{"title":"Use a reflexive only when its role needs one","explanation":"Ordinary English often omits reflexives with routine personal-care verbs: she washed and dressed. A reflexive is not a generally more polite substitute for me or I. In a coordinated subject, use I in formal standard prose.","pattern":"Please contact Sam or **me**.","commonMistakes":["Please contact myself is not the ordinary formal choice when no matching subject creates a reflexive relationship."],"examples":["“The supervisor asked Sam and **me** to prepare the visitor guide.” Choose the standard object pronoun for the speaker.","“The supervisor asked Sam and **me** to restore the old portrait.” Choose the standard object pronoun for the speaker."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reflexive"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Distinguish doing something to yourself, doing it alone and doing it to one another.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"The same participant twice","explanation":"A reflexive pronoun can be used when the subject and object refer to the same person or thing. Its form matches the subject: myself, yourself, himself, herself, itself, ourselves, yourselves, themselves.","pattern":"She introduced **herself**.","commonMistakes":["Her and herself are not interchangeable: her normally refers to someone other than the subject in this example."],"examples":["“She prepared the visitor guide by **herself**.” Choose the matching reflexive.","“She restored the old portrait by **herself**.” Choose the matching reflexive."],"skill":"form","id":"reflexive-reciprocal-foundation-1","domain":"reference","referenceIds":["bc-reflexive"],"readingVersion":"core-2026-09-v3"},{"title":"Emphasis and independence","explanation":"A reflexive can emphasise that the subject personally did the action. **By + reflexive** usually means alone or without help. **For + reflexive** means for one’s own benefit. These meanings are related but not identical.","pattern":"I made it **myself**. / I did it **by myself**.","commonMistakes":["By myself says without company or help; for myself says who benefits."],"examples":["“We prepared the visitor guide by **ourselves**.”","“We restored the old portrait by **ourselves**.”"],"skill":"meaning","id":"reflexive-reciprocal-foundation-2","domain":"reference","referenceIds":["bc-reflexive"],"readingVersion":"core-2026-09-v3"},{"title":"Reciprocal actions","explanation":"Each other and one another express a reciprocal relationship: A acts on B and B acts on A. They are not equivalent to themselves, where each participant’s action returns to that same participant.","pattern":"They introduced **each other**.","commonMistakes":["They looked at themselves means each looked at their own reflection; each other means they looked across at one another."],"examples":["“The two assistants helped each other to prepare the visitor guide.” What does “each other” show? → **Each assistant helped the other assistant.**","“The two assistants helped each other to restore the old portrait.” What does “each other” show? → **Each assistant helped the other assistant.**"],"skill":"contrast","id":"reflexive-reciprocal-foundation-3","domain":"reference","referenceIds":["bc-reflexive"],"readingVersion":"core-2026-09-v3"},{"title":"Use a reflexive only when its role needs one","explanation":"Ordinary English often omits reflexives with routine personal-care verbs: she washed and dressed. A reflexive is not a generally more polite substitute for me or I. In a coordinated subject, use I in formal standard prose.","pattern":"Please contact Sam or **me**.","commonMistakes":["Please contact myself is not the ordinary formal choice when no matching subject creates a reflexive relationship."],"examples":["“The supervisor asked Sam and **me** to prepare the visitor guide.” Choose the standard object pronoun for the speaker.","“The supervisor asked Sam and **me** to restore the old portrait.” Choose the standard object pronoun for the speaker."],"skill":"application","id":"reflexive-reciprocal-foundation-4","domain":"reference","referenceIds":["bc-reflexive"],"readingVersion":"core-2026-09-v3"},{"domain":"reference","id":"reflexive-emphasis-and-by","title":"Reflexive, emphatic and by-myself meanings","explanation":"A reflexive pronoun can be an object referring back to the local subject. The same form can add emphasis, and by + reflexive commonly means alone or without help. These meanings are related but grammatically distinct. An ordinary object pronoun points to a different person unless a special context supplies another interpretation.","pattern":"She hurt **herself**. / She **herself** explained it.","examples":["I repaired it **myself**.","The children travelled **by themselves**."],"commonMistakes":["Do not use myself merely as a more formal substitute for me: please contact Sam or me. Reflexive licensing depends on the structure."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["She introduced **herself**.","I made it **myself**. / I did it **by myself**.","They introduced **each other**.","Please contact Sam or **me**."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["question-tags"],"readingReferenceIds":["bc-reflexive","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reflexive-reciprocal'
